quests[12227] = { id = 12227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing Your Duty", description = "Alright, {race}. Here's the juice.\n\nIt works immediately, so don't use it until you're safely inside the outhouse.\n\nNow go get me those seeds!", progress = "Got those seeds for me yet, {race}?", completion = "Well, {name}? Everything come out okay?\n\nHmm, looks like we caught 'em just in time....", objectives = "Anderhol in Amberpine Lodge wants you to take the Anderhol's Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12229] = { id = 12229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Link", description = "Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.\n\nFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier.\n\nBring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.", progress = "Have you obtained the blood samples, {name}?", completion = "This blood carries the same taint as the slime you obtained earlier... this does not bode well, {name}.", objectives = "Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12230] = { id = 12230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing from the Siegesmiths", description = "I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with!\n\nTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.\n\nLuckily for us, they also leave their bombs lying about. \n\nI want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.", progress = "You'd think that they'd let me make use of the blight spreaders... maybe load them up with something nasty to destroy the ballistae.\n\nBut no, they tell me that they're only for special missions.\n\nWhatever!", completion = "<The deathguard rubs his hands together in anticipation.>\n\nExcellent. Their loss is my... our gain!\n\nYou didn't have trouble with any of these along the way? Some of them look rather unstable. I may be undead, but I value my existence!", objectives = "Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12231] = { id = 12231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear God's Offspring", description = "It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence.\n\nThe shrines that they guard to the east are home to Ursoc's offspring.\n\nIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.\n\nIf that's the case, find them and listen to what they have to say.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far.", objectives = "Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart's Blood Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12232] = { id = 12232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombard the Ballistae", description = "At last, our chance to strike at their siege engines! Don't flub it.\n\nI kid.\n\nA little.\n\n{class}, bombard New Hearthglen's ballistae with these bombs.\n\nWe'll show the Royal Apothecary Society how it's done old style. No concoctions required!", completion = "Oh happy day!\n\nBy not using the time and resources of the apothecaries to get the job done, I'm sure to attract the attention of the high executor!\n\nThinking outside the box, that's what I'm all about. Yes, yes, you had a hand in helping too.\n\nHere, if I give you something will you promise to not mention your part in all of this?", objectives = "Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12234] = { id = 12234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need to Know", description = "I need to know what New Hearthglen is up to.\n\nI want you to steal their orders of the day so that I can find that out.\n\nHead south and in their abbey, in their barracks, and on their beach, find those daily plans!\n\nJust in case you're confused, the barracks is the large building right next to the smithy.", progress = "If you take too long, their daily plans will change, and we may have to start over again.\n\nDon't take too long!", completion = "Well, what are you waiting for, {race}? Hand them over!", objectives = "Spy Mistress Repine at Venomspite has asked you to steal the Scarlet Onslaught Daily Orders: Abbey, Scarlet Onslaught Daily Orders: Barracks, and Scarlet Onslaught Daily Orders: Beach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12235] = { id = 12235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naxxramas and the Fall of Wintergarde", description = "Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute.\n\nWe must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed.\n\nLeave me!", completion = "<Urik points to a gryphon.>\n\nHave you ever ridden one of those? It's simple, friend. Just hop on and tell it where to go.", objectives = "Speak with Gryphon Commander Urik at the gryphon station in Wintergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12236] = { id = 12236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, the Bear God", description = "The time has come, {name}.  Now we will learn whether our efforts will accomplish what we need or nothing at all.\n\nTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw.\n\nConvince Tur to aid you, for you will need all the help you can get.\n\nOnce you've defeated the bear god, use these ashes over his body.\n\nEven if his worldly form is destroyed, his spirit must be saved.", progress = "You've returned.  Did you succeed?", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>", objectives = "Windseer Grayhorn in Conquest Hold wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12237] = { id = 12237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight of the Wintergarde Defender", description = "With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station.\n\nThere are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!", progress = "Hurry, {name}! You need to save the helpless villagers!", completion = "Outstanding work, {name}! We can get this keep back into working order now with the return of our citizens.", objectives = "Rescue 5 Helpless Wintergarde Villagers and return to Gryphon Commander Urik at Wintergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12238] = { id = 12238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Drak'Tharon", description = "Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!", objectives = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12239] = { id = 12239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spy in New Hearthglen", description = "I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault.\n\nShe goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker.\n\nHere, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.", progress = "<The agent eyes you up and down, and then silently motions you over.>\n\nDon't blow my cover, {class}!", completion = "You have word from the spy mistress?\n\n<The agent looks around to make sure that no one is watching as she puts down her shovel.>\n\nLet me see those plans.", objectives = "Deliver the Scarlet Onslaught Daily Orders to Agent Skully at New Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12240] = { id = 12240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Means to an End", description = "I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you.\n\nThe lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman.\n\nI think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running.\n\nReady to take him out, {class}?", completion = "I knew my sister wouldn't let us down.\n\nWell done, {name}. The Onslaught's lumbermill will be out of commission for a while, which means no new construction or ballistae.\n\nThanks for helping me to live up to the family name.", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use the Levine Family Termites to lure Foreman Kaleiki out and kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12241] = { id = 12241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Sapling", description = "The furbolgs' work must be undone, {name}.  The best of intentions do not count for much when the result is tainted by such strong a corruption.\n\nThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.\n\nOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.", progress = "Have you brought me the ashes, {name}?", completion = "I can't make any promises, {name}.  But I will try my best to purify these.", objectives = "Windseer Grayhorn in Conquest Hold wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Windseer Grayhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12242] = { id = 12242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Seeds", description = "We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.", progress = "Have you obtained Vordrassil's seeds yet, {name}?", completion = "Thank you, {name}.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12243] = { id = 12243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Upon the Waters", description = "I have another mission for you.\n\nI was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze!\n\nUse it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters.\n\nYou'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.", progress = "Please do NOT tell me that their sails were somehow protected from my burning water!\n\nI'd hate to have to test it out here again.", completion = "Ahhahahahahahahahaha!\n\nWithout their rutters, they've got nowhere to run to now.\n\nLooks to me like the end of the Scarlet Onslaught, and just when they were getting started. How sad.\n\nHeh.", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use her Apothecary's Burning Water to set the sails of the Sinner's Folly afire.\n\nWhile the deckhands are busy attempting to put the fires out, head belowdecks and retrieve Captain Shely's Rutters from the captain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12244] = { id = 12244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Repair", description = "Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday....\n\nNo wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde!\n\nWhile you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.", completion = "<Synipus whistles.>\n\nOh, she's a beauty! We'll fix her up nice.\n\nIf you're short on things to do, go talk to Gordun and get a ride down to Venture Bay. They're sure to need a hand.\n\nOh, and while you're there, use these keys on a Refurbished Shredder. Wait 'til ya see what these babies can do when they're cleaned up!", objectives = "Synipus at Blue Sky Logging Grounds wants you to bring 3 Broken-down Shredders back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12245] = { id = 12245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Captured", description = "We have more fools for you to kill.\n\nMy agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught.\n\nThis will not do.\n\nGo back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke and Chancellor Amai.\n\nFrom what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture.\n\nSpeak with them and then kill them!", completion = "What? You were expecting us to have you rescue them?\n\nNow why would we do that when they have a proven track record of getting themselves captured in the first place?\n\nNorthrend is a cold place, young {name}. I suggest that you adjust to it.", objectives = "Spy Mistress Repine has asked you to slay Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke, and Chancellor Amai.\n\nWhen you've accomplished this task, report your success to High Executor Wroth at Venomspite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12246] = { id = 12246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Link", description = "The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses.\n\nTheir condition could be linked with the contaminants we found on Vordrassil's remains.\n\nBring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.", progress = "Have you obtained the blood samples, {name}?", completion = "The corruption present in this blood is identical to that of the slime.  I don't have a good feeling about this.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12247] = { id = 12247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of Ursoc", description = "The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence.\n\nWhat remains to be seen is whether the bears they worship as gods have also been tainted.\n\nUrsoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.\n\nSee if they will speak to you regarding what has happened here.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to speak to Orsonn at the Rage Fang Shrine and Kodian at the Heart's Blood Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12248] = { id = 12248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Sapling", description = "The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it.\n\nOn the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling.\n\nTake this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.\n\nBring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.", progress = "Have you brought me the ashes, {name}?", completion = "Yes!  Vordrassil's magic is still present in these ashes.  There might be hope for Ursoc yet.", objectives = "Hierophant Thayreen in Amberpine Lodge wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Hierophant Thayreen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12249] = { id = 12249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, the Bear God", description = "It is time, {name}.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.\n\nYou will need his help.  You won't be able to defeat Ursoc alone.\n\nOnce you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12250] = { id = 12250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Seeds", description = "We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.", progress = "Do you have the seeds, {name}?", completion = "Thank you, {name}.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12251] = { id = 12251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the High Commander", description = "Return to High Commander Halford Wyrmbane at once, {name}. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.", completion = "<Halford salutes.>\n\nThe townsfolk are all back to work? Already? Outstanding, soldier! We'll get this town built back up and fortified in no time. Before long, reinforcements will be ready to join the fight with Lord Fordragon at the Wrathgate.\n\nI'm getting ahead of myself, of course, as there is much left to do here before we can even think about sending you to the aid of Bolvar.", objectives = "Speak with High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12252] = { id = 12252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torture the Torturer", description = "Enough! I want you to put an end to the torture of my people!\n\nThe Onslaught's torturer, Alphonse, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know.\n\nMy sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy.\n\nI'll loan you my personal branding iron to see to it that the job is done right.\n\nFind him and get that information.", completion = "They knew all of that? And who the hell is this Grand Admiral Westwind that he spoke of?!\n\n<The high executor grumbles to himself about hating surprises.>\n\nBetter that we know than have to guess. I hope that you left your... er, my mark.", objectives = "High Executor Wroth at Venomspite wants you to use the branding iron 5 times on Torturer Alphonse to get the information out of him. After that, kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12253] = { id = 12253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue from Town Square", description = "Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.\n\nIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, {name}, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.", completion = "<Halford says a prayer for the deceased.>\n\nYou do the Light's work, {name}.\n\nI fear that our work has only just begun.", objectives = "High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight wants you to rescue 6 Trapped Wintergarde Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12254] = { id = 12254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without a Prayer", description = "These plans indicate something imminent is being planned.\n\nBut first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them.\n\nI've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book.\n\nMaybe it will give us a clue.", progress = "You have the bishop's prayer book? Did you find anything unusual in it?", completion = "A newly scribed blessing at the back of the book you say?\n\n<The agent glances over your shoulder as you flip to the page at the end.>\n\nDamn it all! That's the high abbot's handwriting! I'd stake your life on it.", objectives = "Agent Skully at New Hearthglen has asked you to acquire Bishop Street's Prayer Book.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12255] = { id = 12255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thane of Voldrune", description = "Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson.\n\nThe thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.", progress = "Have you overcome the thane? We cannot risk leaving him in power.", completion = "Good work, {name}. I doubt any of the woodsmen would've wanted to take a crack at the proto-drake, but we couldn't afford to let the Dragonflayers build a base of power in Grizzly Hills. If only the Horde was so easily dealt with...", objectives = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Woodsman Drake at Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12256] = { id = 12256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flamebinders' Secrets", description = "Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us.\n\nTheir most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.", progress = "Did you collect those talismans?", completion = "With the power of the talismans, the drake has no choice but to obey your commands. The thane's fate is sealed.", objectives = "Bring 3 Flame-Imbued Talismans to Sergeant Nazgrim at Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12257] = { id = 12257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Strength", description = "Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk.\n\nWe cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a {class} of the Horde, you will relish the chance to demonstrate our strength.\n\nCut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!", completion = "You have done exactly as I asked. We've got the Dragonflayers on the defensive and it'll soon be time to deal with their leader.", objectives = "Kill 12 Dragonflayer Huscarls and return to Sergeant Nazgrim at Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12258] = { id = 12258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Dead", description = "The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, {name}. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.\n\nVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.", completion = "Perhaps now they will rest easy, their spirits free to ascend to the Light.\n\nMy thoughts and prayers now turn to Lord Fordragon and our forces at the Wrathgate. We must persevere here, if only to buy them enough time to defeat the Lich King. Wintergarde cannot fall.", objectives = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 15 Vengeful Geists.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12259] = { id = 12259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thane of Voldrune", description = "With the flame-imbued talismans, we can finally challenge the thane.\n\nHis favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.", progress = "Have you overcome the thane?", completion = "The few remaining Dragonflayers dare not challenge us after your battle with the thane. Show no mercy to our enemies - that is the way of the Horde.", objectives = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Sergeant Nazgrim at Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12260] = { id = 12260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Dissemblance", description = "You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress.\n\nIt only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests.\n\nBe quick about it... I have no idea how long my glamour will last while you have the mirror.\n\nRealize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.", progress = "Please tell me that you didn't break the mirror?!", completion = "Not bad, {class}. Now that the priest's image is trapped within the mirror, I have something else that needs doing.", objectives = "Agent Skully at New Hearthglen has asked you to steal the image of an Onslaught Raven Priest. Return the Banshee's Magic Mirror to her when you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12261] = { id = 12261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Place to Run", description = "They're drawing power from the bones of my dead brothers...\n\nI have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway.\n\nEnsure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.", progress = "Have you placed the ward?", completion = "Excellent. When they begin to flee in fear, the ward shall be there to wish them a fond farewell.", objectives = "Place a Destructive Ward at the end of the path leading out of Obsidian Dragonshrine, where the road starts to give way to snow. Protect the ward until it is fully charged, then return to Serinar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12262] = { id = 12262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One to Save You", description = "We will spare no one. \n\nOutside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.", completion = "Did they beg for their miserable lives? Weaklings.", objectives = "Kill 6 Burning Depths Necrolytes and 10 Smoldering Skeletons outside of the Obsidian Dragonshrine. Return to Serinar once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12263] = { id = 12263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best of Intentions", description = "The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.\n\nI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. \n\nBe cautious {name}, any damage done to you is likely to break the fragile illusion.", completion = "We are the Black Dragonflight. We have rained destruction on the lands of Azeroth for thousands of years. The decrepit Cult of the Damned worships death and we shall be glad to oblige.", objectives = "Wait for Serinar to administer the disguise of a Burning Depths Necrolyte, then proceed to the back of the Maw of Neltharion to uncover what the Cult of the Damned is doing there. Return to Serinar with details regarding their purpose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12264] = { id = 12264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Damned", description = "The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.", completion = "Hearing their screams... watching the last life fade from their wretched bodies... it's invigorating, is it not?\n\nI relish it.", objectives = "Kill 3 Burning Depths Necromancers, 6 Smoldering Constructs, and 6 Smoldering Geist in the Maw of Neltharion, and then return to Serinar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12265] = { id = 12265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiling the Defilers", description = "I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one.\n\nDestroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.", completion = "Good. There is more to be done.", objectives = "Locate and stamp out 8 Necromantic Runes that have been drawn on the floor inside the Maw of Neltharion. Return to Serinar once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12266] = { id = 12266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tales of Destruction", description = "You can leave now, {race}.\n\nGo tell Nalice she missed out on a good slaughter.", completion = "Oh, it's you.\n\nI had hoped Serinar would simply return himself once the task was done... I suppose he's distracted by something or another to kill. He's missing out on a gloriously messy battle!\n\nAre you still here? I'm done with you.", objectives = "Travel back to Wyrmrest and let Nalice know that Serinar's task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12267] = { id = 12267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Flame", description = "With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption.\n\nRothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame.\n\nBurning the bones will surely gain Rothin's attention, see to it that he is destroyed as well.\n\nThe magic in this vial should see the task done.", progress = "You are quite an effective tool, {class}. Your hand in this purging is appreciated.", completion = "The bones of my brood have been spared this filth. You have served me well, and as such, you shall be awarded appropriately.", objectives = "Use Neltharion's Flame to douse the summoning area in the back of the Maw of Neltharion. Once you get the attention of Rothin the Decaying, kill him, then return to Serinar at the front of the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12268] = { id = 12268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces Parts", description = "Ack! This thing's a mess!\n\nGoblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with.\n\nGive me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.", progress = "Got those parts for me, {class}?", completion = "Yes indeed. These should do the trick...\n\nThere. One more shredder ready for the fight. Thanks, {name}.", objectives = "Pipthwack in Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12269] = { id = 12269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In Our Mine", description = "That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine!\n\nThe supply line must be halted and our lost brothers must be put to rest.\n\nTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.", progress = "Did you recover their cards?", completion = "<Leoric takes the cards from you.>\n\nI will get these to our recorder and deliver the grim news to the families of the miners.\n\nThere is still much to be done if we are to succeed here and ultimately at the Wrathgate. Lord Fordragon is depending on us.", objectives = "Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight wants you to recover 10 Wintergarde Miner's Cards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12270] = { id = 12270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shred the Alliance", description = "Read my lips, {class} - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance!\n\nThey've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine!\n\nYou see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it.\n\nDismissed!", completion = "Good work, soldier!\n\nNow take this key and get yourself down to Venture Bay. It'll let you use one of the refurbished shredders to unleash chaos on our enemies.\n\nOh yes, and talk to Darrok if you want to take the shortcut!", objectives = "Grekk at Blue Sky Logging Grounds wants you to acquire 3 shredders and return to him with them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12271] = { id = 12271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rod of Compulsion", description = "A rod drops from Alphonse's dead hand. There are pulsing magical runes along its length.\n\nCould this be how he was getting his confessions?\n\nBetter let the high executor have a look at it.", progress = "Did you get that rod from their torturer?", completion = "LeCraft had it you say? That makes sense.\n\nI recognize it from my youthful days as a torturer in the court of King Terenas of fallen Lordaeron. It's known as a rod of compulsion.\n\n<The high executor wrings his hands together in evil anticipation of what's to come.>\n\nI have an idea for how we can make good use of it!", objectives = "Deliver the Torturer's Rod to High Executor Wroth at Venomspite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12272] = { id = 12272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bleeding Ore", description = "Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.\n\nYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!", progress = "Have you recovered samples of the strange ore?", completion = "This might be the moment, the very second, that the tide turns against the Scourge. You have proven yourself as a hero of the Alliance, at least in my eyes, {name}.\n\nNow if you would be so kind as to give me some space. I will require additional time to study this ore in order to isolate impurities and weakness.\n\nCarry on, ally. I will contact you once I have an update.", objectives = "Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12273] = { id = 12273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Denouncement", description = "It's time for us to utterly demoralize the Onslaught forces!\n\nI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.\n\nPlace them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!", completion = "<You think you see just the hint of a smile cross Wroth's face before quickly disappearing.>\n\nYou're now my favorite {class}, {name}. If you have a mind to, I'd like you to think about joining up as an officer in the Hand of Vengeance.\n\nWe can start you out as a deathguard, and in a few decades I think you have what it takes to make junior executor!\n\nNo? Well don't be too hasty... take your time and mull it over.", objectives = "High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer.\n\nOnce the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12274] = { id = 12274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fall From Grace", description = "We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.\n\nUnfortunately, we need to separate him from his bodyguards or you'll never get any information out of him.\n\n<The agent leans on her shovel and thinks a moment.>\n\nI think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.", progress = "What did you find out? Have you even talked with him yet?", completion = "What the hell is going on here?!\n\nHe jumped on his own? You're certain that you didn't push him?\n\n<The agent narrows her eyes at you.>\n\nFine. Clearly there's much more going on in this place than we first thought.", objectives = "Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12275] = { id = 12275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demo-gnome", description = "Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge.\n\nAn entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!", completion = "I feel terrible about this, friend. I fear that in my haste to recover the strange ore from Wintergarde Mine I may have doomed agent Slinkin.", objectives = "Speak with Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12276] = { id = 12276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Slinkin", description = "While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.\n\n<Quarterflash holds up a tiny mechanical toy.>\n\nThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.\n\nWhen you are ready to begin your search, place the bot on the ground next to me.", completion = "<There is a note in Slinkin's death grip.>\n\nChased into a dead end. Hidden for now, but they know I'm here. It won't be long until they find me.\n\nThe miners work tirelessly to unearth the strange ore that fuels the Scourge war machines. There is much banter. The language of death confounds me, but I have been able to identify commonly uttered sounds and phrases. The word \"Yogg-Saron\" is said with great contempt and is usually followed by loud outbursts. They refer to the ore as \"saronite.\" Meaning?", objectives = "Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash's Homing Bot if you need help finding the mine.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12277] = { id = 12277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Nothing to Chance", description = "If there is good in your heart and your conscience is clear, read on.\n\nIn this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine.\n\nYou must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.", completion = "His death will not have been in vain, friend. The information that Slinkin died for will be instrumental in defeating the Lich King. I promise you that we will make this right.", objectives = "Retrieve a Wintergarde Mine Bomb and use it to blow up the Upper Wintergarde Mine Shaft and the Lower Wintergarde Mine Shaft. Report back to Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight when you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, {name}!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving.", objectives = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12279] = { id = 12279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bear of an Appetite", description = "Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone.\n\nI'm cooking up some food here for us, but Griselda'll have none of it.\n\nShe's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while.\n\nNow, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?", progress = "If you don't hurry, it'll be more than just her stomach growling...", completion = "You! You're not Limpy Joe!", objectives = "Bring 6 Northern Salmon to Hugh Glass at the Redwood Trading Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12280] = { id = 12280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Repairs", description = "Twenty shredders by noon tomorrow!\n\nWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....\n\nIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?\n\nI need cogs, sprockets and springs. They're littered across the ground down by the shredders.", progress = "Ya fetch those parts for me yet?", completion = "Thanks, {name}. That should keep me going - at least until tomorrow....\n\nHere's the cash I promised.", objectives = "Lurz at Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12281] = { id = 12281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Scourge War Machine", description = "We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine.\n\nTake this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.", progress = "I heard about your bravery in the mine, {name}.", completion = "<Halford opens the package and reads the analysis.>\n\nI am by no means a scientist, {name}, so you'll have to forgive my plebian understanding of what has been written. Now, according to this analysis - assuming I have the brain power of at least an adolescent school boy - we still don't know jack squat about the Scourge war machine. The only thing we do know is that the Scourge uses this foul metal to craft its siege engines, armor and weaponry.", objectives = "Deliver Quarterflash's Package to High Commander Halford Wyrmbane at Wintergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12282] = { id = 12282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprints on the Past", description = "The memories of the past haunt this land, {name}. I hear the cries of the fallen echo across Northrend - calling to me.\n\nArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.\n\nFirst, you must recover my scrying orb from the town hall, {name}. Exit this tower and turn left down the path to reach the town square.", progress = "Have you recovered my scrying orb?", completion = "Well done, {name}. As fate foretold, you will be the one to carry us through these hard times. Now the long journey begins.", objectives = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to recover his Scrying Orb.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12283] = { id = 12283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Will Out", description = "We have to figure out what's going on here. We need the general's diary!\n\nI'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill.\n\nOnce you acquire the diary, take it to the high executor back at Venomspite.\n\nYou'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me.\n\n<The agent smirks.>", progress = "It's about time, {name}! What's been keeping you?", completion = "Damn it all! Why couldn't you have come to me with good news?!", objectives = "Agent Skully has asked you to acquire The Diary of High General Abbendis and to deliver it to High Executor Wroth at Venomspite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12284] = { id = 12284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep 'Em on Their Heels", description = "We've suffered heavy casualties here, {race}.\n\nThe only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now.\n\nNo matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend.\n\nWe've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.", completion = "Fifteen down, eh? Good to hear it, {class}.\n\nIf nothing else you've bought us a bit of time - at least a day by my figuring.\n\nHere's your pay.", objectives = "Commander Bargok wants you to kill 15 Alliance units or players in Blue Sky Logging Ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12285] = { id = 12285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Unto Others", description = "Their attack is imminent, {class}. I need you to get in there and sever the head of the Scarlet Onslaught, literally!\n\nIt's not going to be easy... Abbendis is sure to be surrounded by a great many of her men.\n\nBring back her head and I'll see to it that you're properly rewarded for saving Venomspite.\n\nFail and don't even bother to return!", progress = "Should I tell my forces to begin making our way toward Agmar's Hammer?\n\nOr did you manage kill the high general?", completion = "Let's see them bring her back to life without her head!\n\n<The high executor's laugh draws a number of furtive glances.>\n\nI'm a little concerned that you let this grand admiral get away, but you're still the hero of the day, {name}!\n\nTake your pick... you've earned it!", objectives = "High Executor Wroth at Venomspite has ordered you to return with The Head of the High General.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12287] = { id = 12287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orik Trueheart and the Forgotten Shore", description = "I have gazed upon the orb and seen the path that you must walk, {name}.\n\nMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.\n\nTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.", completion = "Zelig sent word, friend. We have been expecting you.\n\nI am Orik Trueheart, paladin of the Argent Crusade. The priestess standing across the campfire from me is Tilda Darathan. We are here on behalf of the Argent Crusade - sent to quell the unfortunate damned souls attempting to escape Wintergarde.", objectives = "Seek out the assistance of Orik Trueheart at Dawn's Reach in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12288] = { id = 12288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelmed!", description = "You there, {class}! Help me!\n\nWe're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether!\n\nTake this tourniquet and use it on the wounded down on the battlefield.\n\nHurry, {name}! They're dyyying!!", completion = "Oh, thank you, thank you.\n\nYou've helped us to live another day. Perhaps there's hope yet.", objectives = "Aumana at Blue Sky Logging Grounds wants you to use the Renewing Tourniquet on 10 Wounded Skirmishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12289] = { id = 12289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick 'Em While They're Down", description = "It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them.\n\nWith the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail!\n\nGo, {name}. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!", completion = "Well done, {name}.\n\nYou've bought us some time here, though likely no more than a day. Nevertheless, the Alliance is grateful for your efforts.", objectives = "Sergeant Hartsman wants you to defeat 15 Horde units or players in Blue Sky Logging Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12290] = { id = 12290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Murkweed Elixir", description = "The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them!\n\nTo the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.", progress = "Have you recovered the murkweed?", completion = "<Orik takes the murkweed and begins mixing an elixir.>\n\nIt won't be much longer, {name}.", objectives = "Orik Trueheart at Dawn's Reach in Dragonblight wants you to recover 5 Murkweed from the Eldritch Heights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12291] = { id = 12291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten Tale", description = "The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.\n\nOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.\n\nRemember, {name}, these spirits were once Alliance soldiers. Treat them with respect, honor, and dignity.\n\nNow, with elixir in hand, venture south to the Forgotten Shore.", progress = "I have enough murkweed to make more elixirs, {name}.", completion = "<Orik's eyes fill with tears.>\n\nThey don't know. None of them know! They think Arthas to be some great hero, when in truth it was Arthas who ordered the ships to be burned. It was Arthas who left us all for dead in this frozen wasteland!\n\n<Orik weeps.>\n\nNot all of the soldiers from the Prince's fleet perished in the freezing winter. I was only a lad when I was given the chance to battle the Scourge... to save our home from certain destruction. I took that chance, {name}.", objectives = "Hear the tales of a Forgotten Peasant, Forgotten Rifleman, Forgotten Knight, and Forgotten Footman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12292] = { id = 12292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Local Support", description = "We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate.\n\nUntil this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort.\n\nWe get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.", progress = "You bring me that box, {name}?", completion = "It's locked, isn't it?  It looks pretty ordinary.\n\n<Lieutenant Dumont Shakes the chest, producing a rattling wooden sound.>\n\nNo matter, I suppose.  If this gets us the edge we need against the Horde, then I could care less if the cure for the Plague was in there.", objectives = "Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12293] = { id = 12293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close the Deal", description = "We have what the trappers want.  Now it's up to us to sign them up with our side.\n\nTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of here.\n\nIf all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.", progress = "You've brought something for us?", completion = "You did it!  You recovered the Sc... you recovered the chest that the Horde stole from us.  We thank you, {name}.", objectives = "Bring the Cedar Chest to Ivan at Aspen Grove Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12294] = { id = 12294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tentative Pact", description = "Very well, {name}.  Your people kept their end of the bargain.\n\nTell Dumont that we'll honor the deal.", completion = "Excellent news, {name}.  With the locals' help we'll have the logistical support we need to outmaneuver the Horde in this region.\n\nI have further tasks for you if you're interested.", objectives = "Return to Lieutenant Dumont in Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12295] = { id = 12295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exercise in Diplomacy", description = "We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs.\n\nThis should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress.\n\nGo to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges.", completion = "It's good to finally meet you, {name}!  We'd heard about you up here.  Welcome to Silverbrook.\n\nThese trappers are a great bunch of lads and lasses.  Hardy people, they know the lay of the land really well.  You'll find it's a great thing that we finally won them over to our side.", objectives = "Speak to Envoy Ducal in Silverbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12296] = { id = 12296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life or Death", description = "Oh, the carnage....\n\nI've been through many battles, {class}, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death.\n\nIf we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone.\n\nI've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.", completion = "Wonderful!\n\nThe Alliance shall live to see another day, in part due to your diligence.\n\nPlease accept my thanks, friend.", objectives = "Rheanna at Blue Sky Logging Grounds wants you to use the Renewing Bandage on 10 Wounded Westfall Infantry units.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12297] = { id = 12297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!", progress = "Hello, {class}.", completion = "<Greer lifts his glasses onto the top of his head and reads the note, looking back up at you curiously when he's done.>\n\nYou will have my fastest gryphon! This information must be delivered to High Commander Wyrmbane at once!", objectives = "Captain Adams has asked you to show the Alliance Missive to Greer Orehammer at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12298] = { id = 12298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Commander Halford Wyrmbane", description = "<Greer hands the missive back to you.>\n\nSkysong will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait...", objectives = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12299] = { id = 12299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Hospitality", description = "It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing.\n\nYou'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are?\n\nLet's see if our new allies can back all their talk with some action.", completion = "Not bad, not bad.  You might not be as soft as some of the others.", objectives = "Sergei at Silverbrook wants you to slay 8 Conquest Hold Marauders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12300] = { id = 12300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Mettle", description = "Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage.\n\nAround these parts, you're not a real hunter unless you wear your prey's skin.\n\n<Sergei unsheathes his skinning knife and hands it to you.>\n\nThe leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest.\n\nThat's right.  You're going to skin the monster.", progress = "The people in Silverbrook... they're not what they seem.", completion = "Don't do it, {name}.  The people that sent you here.... you shouldn't trust them.", objectives = "Find Sergeant Bonesnap northwest of Silverbrook and pass the Test of Mettle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12301] = { id = 12301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Shall Set Us Free", description = "Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years, whenever I would feel anger, anxiety, or sorrow over the events that transpired here, I was to focus my thoughts upon the orb.\n\nI now understand why Zelig gave this crystal to me.\n\nTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.", progress = "Is it done?", completion = "<Orik beams a smile at you.>\n\nYou did a good thing this day, {name}. Hundreds of lost souls are now redeemed, thanks to you.", objectives = "Use Orik's Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12302] = { id = 12302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Warning", description = "Thanks for helping me, {name}.  My name's Sasha.  Listen, I have to get the hell out of here.\n\nThe people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them.\n\nThis... 'test' they sent you on is just the beginning.\n\nHead to the northwestern end of Silverbrook.  You'll find something of interest to you.\n\nGood luck... and trust no one.", completion = "Who's there?  Are you here to kill me?\n\nPlease!  You don't have to do this!", objectives = "Go to the northwestern end of Silverbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12303] = { id = 12303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funding the War Effort", description = "<The quartermaster lowers his voice and whispers to you.>\n\n{class}, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.\n\nBut, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.\n\nWe have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!", progress = "How much of that Alliance treasure did you manage to get your hands on?", completion = "<The quartermaster gasps, but then his eyes narrow as he studies you for a moment.>\n\nI trust that you didn't stash any of this on the side for yourself? You wouldn't be that selfish when the fate of Venomspite is at stake?\n\nBesides, I'm going to reward you with a percentage of the take. It's not much, but in times like this, we all have to make sacrifices.", objectives = "Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12304] = { id = 12304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beachfront Property", description = "It's time for Venomspite to expand!\n\nWe'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!\n\nUnfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead.\n\nClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.", completion = "Can't you just see it now, {class}? It'll be the vacation spot of Northrend!\n\nWhat do you think of the name, \"Hansen's Cove\", or maybe \"{name} Bay\"? Kind of catchy, don't you think?", objectives = "Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12305] = { id = 12305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Thoughts", description = "You have honored me and honored the memory of hundreds of Alliance veterans, {name}. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.\n\nI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.\n\nFarewell.", completion = "<Zelig smiles.>\n\nIt is I who owe you a debt of gratitude, hero. Orik is like a brother to me. You have changed his life and given renewed hope to countless others.", objectives = "Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, {name}?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like.", objectives = "Bring the \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12307] = { id = 12307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsbane Root", description = "Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.\n\nWe spent all of last week cutting them down, but the roots are beginning to sprout again.\n\nIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?", completion = "<Katja reels away from you nervously.>\n\nThank you, {name}.  You didn't get any wolfsbane on you, did you?  I've got these... allergies that act up once in a while.", objectives = "Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12308] = { id = 12308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!", completion = "Worgen.  Blasted, Light-forsaken, filth-ridden worgen.\n\nIt's time we showed the locals what us civilized folk do with beasts like them.", objectives = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12309] = { id = 12309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Durkon!", description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested assistance. You will find him and help him, {name}. The crypt is on the western border of the town square.", completion = "Oh brother, it's a mess down there! I barely made it out last time - which is what prompted my request to the High Commander.\n\n<Durkon looks you up and down.>\n\nYou got that crazy look in your eyes, {race}. Thankfully, you're gonna need to be crazy to do what I'm about to ask of you.", objectives = "Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12310] = { id = 12310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Response", description = "Our response must be immediate.  Decisive.  We must teach these savages not to cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.", completion = "It's a shame those trappers turned out to be... afflicted.  We sure could've used a few more fighting men.\n\nMay the poor souls rest in peace.", objectives = "Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12311] = { id = 12311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Noble's Crypt", description = "Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!\n\nAnd {name}, be on the lookout for any information that might be laying about inside the room where Amarion resides.", completion = "Now if we could stop the Scourge attacks coming from outside the keep we might be able to send help to Lord Fordragon at the Wrathgate.", objectives = "Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12312] = { id = 12312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Scourge", description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.\n\nDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.", progress = "A Scourge tome?", completion = "Whatever information is held in this book must be of great importance! I could hear the howls and wails echoing through the crypt as you made your escape!\n\nThe High Commander must be notified!", objectives = "Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12314] = { id = 12314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With Captain Zorna!", description = "The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, {name}, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.", completion = "Well done, {name}! Without their leader, the Horde is weak and disorganized. I will order our men forward.", objectives = "Slay Captain Zorna and report to Baron Freeman at Venture Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12315] = { id = 12315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Captain Brightwater!", description = "With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!\n\nThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.\n\nThis will be no easy fight, {name}. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!", completion = "You are a true soldier of the Horde, {name}. Your bravery will inspire my men to victory!", objectives = "Slay Captain Brightwater and report to General Khazgar at Venture Bay.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12316] = { id = 12316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay!", description = "We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.\n\nGo into the field, {name}, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!", completion = "Your bravery has inspired the men of the Westfall Brigade. Even now they fight with greater ferocity. The port will soon be ours.", objectives = "Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12317] = { id = 12317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay", description = "This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, {name}. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We don't want to keep Conqueror Krenna waiting.", completion = "The port will soon fall to us. You have done well this day, {name}.", objectives = "Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot! The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths. Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths. He'll know more of Direbrew's plot.\n\nFind our spy. Save Brewfest!", sourceObjective = "Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[12319] = { id = 12319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Tome", description = "What can it be, {name}? That was certainly no ordinary curse that the blasted lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.", progress = "The necrolord is no more?", completion = "<Halford's eyes widen.>\n\nThe fates smile down upon us on this day, {name}. I know just the person to see about this tome.", objectives = "Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12320] = { id = 12320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Language of Death", description = "Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.\n\nGo now!", progress = "You come from high command, my son?", completion = "Perhaps, with proper motivation, Godfrey will tell us what he knows about the tome.\n\n<Hallard turns to Mayor Godfrey.>\n\nIsn't that right, mayor?", objectives = "Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12321] = { id = 12321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Righteous Sermon", description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.", completion = "We should have known about the damned mausoleum. This is preposterous! Duke August Foehammer and Ambo Cash will be dispatched to the front lines in preparation for our next assault.\n\nOnce you have cleared the mines I will send you to Foehammer so that we may begin our attack against the Scourge of Naxxramas!\n\nThe information you have garnered thus far will be sent to Lord Fordragon at the Wrathgate upon the wings of our most able gryphon!", objectives = "Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12323] = { id = 12323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.", completion = "Well done, soldier! Now the rest of the men can focus their efforts on the Horde.", objectives = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12324] = { id = 12324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.", completion = "The general will be pleased that you've dealt with the Venture Company problem. Now, the men can focus on beating back the Alliance.", objectives = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12325] = { id = 12325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Hostile Territory", description = "You have done much to advance our efforts against the Scourge, {name}. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!", completion = "Ah, the distinguished hero arrives. Welcome to ground zero, {name}. Allow me to bring you up to speed!\n\nThel'zan's most powerful forces have made their way into the Wintergarde Mausoleum. They plumb its depths in search of corpses and souls to send against Wintergarde while Naxxramas rains down terrible Scourge plague machines, set to hold us at bay!\n\nWe must strike now and hope that Lord Fordragon is able to hold out at the Wrathgate for just a little longer.", objectives = "Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12326] = { id = 12326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steamtank Surprise", description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.", progress = "Name's Cash. Ambo Cash. And the pleasure is all yours.", completion = "Why I'm not wearing any pants isn't important. Let's just say I took some Scourge shrapnel in the wrong place and leave it at that, ok?\n\nSo you wiped out those plague wagons up in the fields and got my soldiers here in one piece. Impressive. You're one of the first to make it this far, friend. Too bad you gotta go right back out into the Carrion Fields. Yep, we've had a bit of a setback.", objectives = "Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12327] = { id = 12327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Body Experience", description = "Ah, you seek a vision of the past.  You're a wise {race}.\n\nEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.", progress = "Yes, {name}?", completion = "Did you learn anything from your vision?  You mentioned Solstice Village during your trance -- which marks the second time someone has spoken the place's name today.", objectives = "Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12328] = { id = 12328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna's Request", description = "I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.\n\nI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.", progress = "Did you obtain the dust, {name}?", completion = "Good.  These will do just fine.\n\nI will have the potion ready for you in no time at all.", objectives = "Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12329] = { id = 12329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate and Coincidence", description = "There are two types of people in this world, {name}.  Those who believe in coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.\n\nEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.", completion = "I was wondering when you'd turn up.  Think you can give me a hand here?", objectives = "Speak to Sasha at the White Pine Trading Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12330] = { id = 12330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatoly Will Talk", description = "My sister is here somewhere, and I can't seem to get this monster to talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.\n\nTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.\n\nI will help you find the person behind all this once we save my sister.", completion = "That... that was close.\n\nWe need to save Anya.  Now!", objectives = "Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village. Bring Tatjana back to the White Pine Trading Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
