quests[12372] = { id = 12372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defending Wyrmrest Temple", description = "Emboldened by the overabundance of magic now flowing through the Azure Dragonshrine, the blue dragonflight has dared to attack Wyrmrest Temple itself!\n\nI ask that you ride one of our defenders into battle to slay their dragons and drakes, and to attack the eruption of ley line energies at the dragonshrine itself in order to destabilize it.\n\nOutside on the east and west terraces are wyrmrest defenders. Speak with one to ride it into battle.\n\nWithout your help, {name}, we will surely lose.", progress = "How fares the fight?  Are we pushing them back?", completion = "Incredible! Let me just say that I continue to be amazed by what you younger races seem capable of.\n\nWe are indebted to you. Will you come back and help us again tomorrow?", objectives = "Devrestrasz at Wyrmrest Temple has asked you to slay 3 Azure Dragons, slay 5 Azure Drakes, and to destabilize the Azure Dragonshrine while riding a Wyrmrest Defender into battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
