quests[12411] = { id = 12411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sister's Pledge", description = "Please, {name}.  I know it is Arugal you're after.  I swear on my father's memory I will help you take him down.\n\nBut I must beg you... Anya is completely innocent, we cannot leave her with these savages.\n\nHelp me rescue my sister and you'll have me at your side when you face Arugal.\n\nI know the den Anatoly spoke of.  We'll find it on the other side of this hill.  Let's go, my sister's in danger.", completion = "I don't want to be here anymore.  The worgen-men are mean.", objectives = "Look for Anya in the Duskhowl Den near Solstice Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12412] = { id = 12412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Enemy's Friend", description = "If there is one thing I can get through your head, let it be this: the Alliance will be crushed in the Grizzly Hills.\n\nThere is far too much lumber, ore, game and strategic territory for us to give up on any single battlefront here.\n\nSo far we've been successful... but there's something that could tip the scales in our enemy's favor.\n\nFar to the east  of here, at the Forest Edge's Post, local trappers seek to join the Alliance.  Slaughter them before they have the chance to do so.", completion = "You're back.  And you're alive.\n\nNow what's this nonsense about worgen?", objectives = "Conqueror Krenna in Conquest Hold wants you to slay 8 Silverbrook Hunters and their leader, Vladek, at the Forest's Edge Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12413] = { id = 12413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack on Silverbrook", description = "A few hours ago, the trappers were nothing but peasants threatening to add their number to the Alliance's.\n\nNow they've become something else... an uncertainty.  I do not like uncertainties.  Go to the hills outside their main town in northern Grizzly Hills, Silverbrook, and help my men crush them.", completion = "Not bad, {name}.  You might be slightly more useful than I initially thought.", objectives = "Conqueror Krenna at Conquest Hold wants you to slay 8 Silverbrook Defenders in the Silverbrook Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12414] = { id = 12414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mounting Up", description = "Cap'n Stoutmantle left most of our calvary... cavlary... uh, horsemen at the fight for Venture Bay.\n\nWe chose a good place to put the camp 'cause there are tons of highland mustangs running around near here and in the Boulder Hills to the northeast. The Cap'n put me in charge of capturing some of 'em.\n\nWill you help? I've got a stick and some string, and there are loads of wild carrots growing near the camp. Pick the carrots and use them with the stick to lure in the mustang, then ride it back here.", progress = "Did you get all the mustangs we'll need?", completion = "Wow! These sure are good horses! I think the Cap'n will be real pleased with our work.", objectives = "Ride 5 Highland Mustangs back to Squire Percy at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12415] = { id = 12415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horse Hollerer", description = "The Alliance's 'Westfall Brigade' is camped far to the north, near Thor Modan. They have foolishly divided their forces to contest our control of Venture Bay, and they have been left without cavalry.\n\nThey're now trying to capture and tame the wild highland mustangs that roam the area around the Westfall Brigade Encampment and Boulder Hills. We must stop them before they're able to replace their lost mounts. Take this and throw it near the horses to drive them away.", completion = "<Soulok nods in approval.>\n\nWell done, {name}. We must not let the Alliance gain any kind of advantage.", objectives = "Scare 15 Highland Mustangs and return to Soulok Stormfury at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12416] = { id = 12416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Iskandar leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", progress = "I'm glad you're still with us, {race}.", completion = "It is a disgusting task, but I thank you dearly for doing it.\n\nThe Scourge cannot be permitted to push any further towards Wyrmrest or we are sure to lose it.", objectives = "Aid Captain Iskandar in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Ceristrasz once you have finished this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12417] = { id = 12417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through one of the other passes to the south or north... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, {race}.", objectives = "Enter the Ruby Dragonshrine through one of the northern or southern passes and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Ceristrasz once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12418] = { id = 12418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, {race}. I will send word to the council of what your kind have accomplished here. Go with our blessing.", objectives = "Enter the Ruby Dragonshrine through one of the northern or southern passes, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Ceristrasz once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12419] = { id = 12419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Ruby Dragonshrine", description = "As you pick up the brooch, its faint glow brightens slightly.\n\nKrasus will want to know of Dahlia's fate. Take the brooch to him at Wyrmrest.", progress = "Hello, {race}. I sense the presence of my Ruby Brooch. Hand it here.\n\nWhat has become of Dahlia?", completion = "Dahlia was taken by the Scourge? This is a sad day for all of us.\n\nI will look to finding a new keeper once the shrine is retaken. Thank you for your efforts... the Ruby Dragonshrine is a sacred place to us, and the sacrifices your kind have made will not be easily forgotten.\n\nIt is good to know there are still heroes such as you - I will call upon you one day. Until that day comes, may your adventures be fruitful.", objectives = "Bring Dahlia Suntouch's Ruby Brooch to Krasus in the Ruling Council Chamber at Wyrmrest and inform him of Dahlia's fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12420] = { id = 12420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, {name}!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving.", objectives = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12421] = { id = 12421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, {name}?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like.", objectives = "Bring the \"Brew of the Month\" club membership form to Ray'ma Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12422] = { id = 12422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tactical Clemency", description = "Listen, {name}.  I need you to act with discretion and speed.\n\nOne of Krenna's top sergeants has captured a trapper outcast outside of Silverbrook.  Now, if things turn out the way they usually do, the prisoner is going to be executed before the day is over.\n\nWe can't let that happen.  You see, the prisoner matches the description of Mikhail's older daughter in his diary.\n\nIf we set her loose and follow her closely, she'll lead us to whoever's controlling the trappers.  Take this letter to her.", progress = "Are you here to kill me?", completion = "You're going to let me go... just like that?  Listen, I don't want any trouble with you... these monsters killed my father and took my sister.  I have other things on my mind right now.", objectives = "Deliver the Letter of Amnesty to the Captured Trapper in Silverbrook Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12423] = { id = 12423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mikhail's Journal", description = "From what you can gather, this journal was written by a denizen of Silverbrook named Mikhail.\n\nIt is written in some variant of the common human tongue.  Perhaps you should bring this back to Conqueror Krenna.", progress = "What's that you've got there?", completion = "Hah!  Is this some sort of joke?\n\nI barely have any use for books I can actually understand.", objectives = "Bring Mikhail's Journal to Conqueror Krenna in Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12424] = { id = 12424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorgonna", description = "This book is written in the pig-tongue the humans use.  It needs to be burned immediately.\n\nHand it to my sister Gorgonna and do not waste my time.", progress = "You have something to show me?", completion = "Could it be?  The man who wrote this journal feared for his daughters' lives so he sent them away from Silverbrook.\n\nWe just captured an outcast in the outskirts of town about the same age as the eldest daughter.\n\nListen, {name}.  There's more happening here than meets the eye... we can't just burn this diary.", objectives = "Bring Mikhail's Journal to Gorgonna in Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12425] = { id = 12425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna the Blind", description = "This trapper business has the potential to be more important than we've accounted for.\n\nIf they're not with the Alliance, there's a good chance they're with the Scourge, which could mean trouble.\n\nOur previous efforts might've paid off, though.  We spotted our former captive meeting with a fortune teller of some sort before we lost track of her.\n\nI'm almost certain now that she will take us to their leader if we can find her again.  Find Ruuna the Blind and see what you can find out.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking.", objectives = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12427] = { id = 12427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Bear Wrestling!", description = "So you're interested in the fights, eh?  Well, Krenna has outlawed pit-fighting for all enlisted combatants.  But you, my friend, are technically a free agent and are not included in this prohibition.\n\nNice loophole, eh?\n\nAnyway, if you're interested I can start you off with something easy, a measly bear.  I'll even let you bring friends along!", progress = "It's not over until you or the bear tips over, friend!", completion = "Nice work, mon!  Here's your cut.", objectives = "Defeat Ironhide inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12428] = { id = 12428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Mad Furbolg Fighting", description = "You're not bad.  Not bad at all.\n\nThink you can take a furbolg?  What about one of those extra-large crazed Northrend furbolgs?\n\nGood, good.  Get your crew together, and head to the ring.  Let's give these folks a show... maybe we can earn some more coin while we're at it.", completion = "Those were some sharp moves, friend!  Lots of bets against you, which is good news cash-wise!", objectives = "Defeat Torgg Thundertotem inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12429] = { id = 12429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Blood and Metal", description = "It's nice to have a real fighter around these parts... we'd only had prisoners and caged beasts for the past few weeks.  The people get bored, ya know?\n\nAnyhow, your next challenge is a genuine iron golem stolen from the depths of Thor Modan... think you can swing it?", completion = "My heart nearly skipped a beat there!  Thought that mound of metal was gonna get ya, mon!", objectives = "Defeat Rustblood inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12430] = { id = 12430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Death Is Likely", description = "I'm gonna shoot straight with ya, kid.  This next contender's a murderer.\n\nLiterally.\n\nHe was to be executed last week, but he strangled the hangman with his left hand, so Krenna's guards sort of let me have him.\n\nFeel free to pass on this one.  I wouldn't blame ya.", completion = "Fancy footwork, fancy footwork.  You really made quick work of that crazy orc, friend.\n\nOdds were against you seven-to-one; made some nice coin on that one!", objectives = "Defeat Horgrenn Hellcleave inside the Conquest Pit and speak to Bookie Vel'jen for a reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12431] = { id = 12431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conquest Pit: Final Showdown", description = "You must've really upset Krenna.  She and Gorgonna have had a spat and you're wanted in the pit immediately.\n\nThere are some wild rumors that it's a fight to the death!  That would be bad news for you, but great news for our business venture!\n\nAt any rate, you can't run away from fate... best get in there on the quick and get it over with.", completion = "What happened today... had to happen.  It doesn't mean I have to be happy about it.\n\nI've freed my people from a tyrant, but I've also lost a sister.  I thank you for your help, {name}.  I wish to be alone now.", objectives = "Defeat Krenna in the Conquest Pit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12432] = { id = 12432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Red Rocket", description = "You there, {race}! Get your lousy carcass over here!\n\nThe Alliance have a shipment of lumber all ready for transport just northeast of here. Since getting our hands on that wood is out of the question, there's only one thing to do - destroy it!\n\nThe goblin at the end of the dock here has some torpedoes all ready to go. He's got all the fuel for them on the docked goblin ship to the north.\n\nGet some fuel, then commandeer one of the torpedoes and ride it into their ship.\n\nDismissed!", progress = "Has that Alliance lumber been burned yet, {class}?", completion = "Ha hah! What a ride, eh {class}?\n\nIf we can't control the resources here, then no one can!\n\nWhen will those puny Alliance pests realize that they are no match for the might of the Horde?", objectives = "General Gorlok at the lighthouse in Venture Bay wants you to destroy the Alliance Lumber Boat.\n\nGeneral Gorlok will only be present at the lighthouse when the Horde has it in their possession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12433] = { id = 12433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", progress = "You got some of that element 115, {name}?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find.", objectives = "Gurtor at the Venture Bay Horde base wants you to bring him a canister of Element 115.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12434] = { id = 12434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Always Seeking Solvent" }
quests[12435] = { id = 12435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Lord Devrestrasz", description = "I abhor the loss of life... any life. But I will not stand idly by and allow Malygos to kill us and defile the temple!\n\nI have appointed Lord Devrestrasz as the commander of Wyrmrest's defenses.\n\nSpeak with Torastrasza to ride a drake down to him.\n\nPlease lend him your aid, {name}. Your involvement with the defense of Wyrmrest will be critical to us prevailing against the blue dragonflight.", completion = "You must be {name}. The queen informed me that you would be coming.\n\nIf you are willing, we are in great need of your assistance.", objectives = "Speak with Lord Devrestrasz at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12436] = { id = 12436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplemental Income", description = "Hail, {class}.  You'll find that here at Conquest Hold, we buy and sell what Krenna wants us to buy and sell... at the price that Krenna wants us to buy and sell.\n\nAll this is stifling business.  I'm hoping to make a little bit of coin on the side and feed our grunts at the same time.  Why don't you go hunt down some stag and bring me the venison?\n\nThey're numerous in the area, so bring me only the best meat.", progress = "You get that venison yet, {name}?", completion = "Nice job, {name}.  These will feed two or three grunts each.  Not bad.", objectives = "Provisioner Lorkran at Conquest Hold wants you to obtain 5 Succulent Venison from  the nearby Tallhorn Stag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12437] = { id = 12437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riding the Red Rocket", description = "Listen, {name}. This battle is as much over resources as tactical supremacy.\n\nI have a mission that could turn the tide in our struggle against the Horde here.\n\nThere are torpedoes at the end of the dock that we can use to take down the Horde's lumber ship to the northwest.\n\nYou'll need to get some of the fuel that's stored on the docked goblin ship just north of here, then ride one of the torpedoes into their transport!", progress = "Has that Horde lumber ship been burned yet, {name}?", completion = "Good to see that you survived that impact. Quite the explosion!\n\nWe can't afford for the Horde to make off with all that lumber.\n\nWell done, {class}.", objectives = "Commander Howser at the lighthouse in Venture Bay wants you to destroy the Horde lumber shipment.\n\nCommander Howser will only be present at the lighthouse when the Alliance has it in their possession.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12438] = { id = 12438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Kreug Oathbreaker", description = "Posted by: Illusia Lune\n\nThe Scourge flesh giant known as Kreug Oathbreaker was responsible for the deaths of my husband, children and my dear friends, the Whisperveils. Those brave enough to take on this bounty will find Kreug in the southeastern reaches of the Carrion Fields.\n\nI demand justice! Kill Kreug Oathbreaker!\n\nIn the event that Kreug is slain, I have pooled money and items together and given them to Highlord Leoric Von Zeldig to give out as a reward.\n\nPlease vindicate us!", completion = "Well done, {name}. I will notify Illusia that a hero has heard her call for help and risen to meet the challenge! Here is your reward.", objectives = "Kill Kreug Oathbreaker and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12439] = { id = 12439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Disturbance In The West", description = "Another force threatens to destroy all that we have worked for, {name}. You must head westward to Stars' Rest. Archmage Modera has sensed a great disturbance in the magical ley lines of our world that must be dealt with immediately!\n\nGo now, {name}! Speak to Rodney Wells at the gryphon station here in Wintergarde and let him know the nature of your mission. He will place you on his fastest gryphon to deliver you to Stars' Rest. Speak with Archmage Modera when you arrive.", completion = "We definitely don't want another sundering, friend. I'll do all that I can to help you on your mission.", objectives = "Speak to Rodney Wells at Wintergarde Keep to secure a ride to Stars' Rest in western Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12440] = { id = 12440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Stars' Rest!", description = "When you are ready I will place you on my fastest gryphon to Stars' Rest. Once you get there, find and speak with Archmage Modera.\n\nGood luck, ally!", completion = "Vas heard my distress call then, eh? Not a moment too soon, friend.", objectives = "Speak with the Image of Archmage Modera at Stars' Rest in western Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12441] = { id = 12441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: High Shaman Bloodpaw", description = "Posted by: Drolfy\n\nWhile out in the Eldritch Heights with my cousins, Skrotee and Brote, a vicious band of wolvar from the Bloodpaw tribe attacked us. We attempted to flee, but I fear they got Skrotee and Brote.\n\nI demand retribution! Is there someone brave enough to venture to the southeastern reaches of Dragonblight, to the Eldritch Heights, and kill High Shaman Bloodpaw and his cronies?\n\nI have given a hefty sum of gold to Highlord Leoric Von Zeldig to disperse to anyone that claims this bounty!", completion = "Outstanding work, {name}! I will notify Drolfy that a hero did rise to meet his challenge and that the cruel Bloodpaw is no more!", objectives = "Kill High Shaman Bloodpaw and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12442] = { id = 12442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Onslaught Commander Iustus", description = "Posted by: Highlord Leoric Von Zeldig\n\nUpon the northeastern path from Wintergarde a battalion of 7th Legion were ambushed and slain by Onslaught Commander Iustus and an army of mindless Scarlet Onslaught zealots. Such cold and calculated actions must be met with force!\n\nWintergarde demands justice! Seek out Onslaught Commander Iustus at Onslaught Base Camp to the northeast and end his miserable existence.\n\nI will hand out the reward for this bounty to any who would dare take up the task!", completion = "At least for now the Scarlet Onslaught suffers a setback in their nefarious plans. You have done Wintergarde a great service, {name}.", objectives = "Kill Onslaught Commander Iustus and return to Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight to collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12443] = { id = 12443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Solvent", description = "Gah! Not again. Another blown gasket....\n\nEvery time one of these goes, lubricant gums up all of the gears. Without solvent, it takes hours to clean.\n\nTell ya what, {race}. There's some fancy rocket fuel on the Venture Company barge in the dock there - element 115 I think they call it. That stuff makes for a great solvent.\n\nGet me one of those and I'll make it worth your trouble.", progress = "You got some of that element 115, {name}?", completion = "Ahh yes. That'll save me hours.\n\nTake this for your trouble, friend. And keep an eye out for more element 115. I'll take all you can find.", objectives = "Barblefink at the Alliance base in Venture Bay wants you to bring him a canister of Element 115.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12444] = { id = 12444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Skirmish", description = "The Venture Company's on its way out of Grizzly Hills.  They used to run logging operations here, but things got a little too dangerous for them.\n\nTheir abandoned sites are up for grabs and we sure as hell can't let the Horde get their hands on them.\n\nThe Blackriver Logging Camp is the smallest of the three logging sites in this zone, but we still need it.  Do your part and fend off the Horde forces.  Any lumber they get here will be made into weapons to be used against us elsewhere.", progress = "How's the hunt going?", completion = "Nice work, {name}.  We could use a few more folks like you up here.  We could really show the Horde not to mess with us.", objectives = "Scout Captain Carter wants you to kill 10 Horde units or players in the Blackriver Logging Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12446] = { id = 12446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Always Seeking Solvent" }
quests[12447] = { id = 12447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Obsidian Dragonshrine", description = "The Scourge come. Korialstrasz calls upon his allies in a futile attempt to save their Ruby Dragonshrine, but it seems the good graces of the red flight don't extend to saving the shrines of the other flights.\n\nSurprised? I'm not.\n\nThere is another of my brood who has left to clear our Obsidian Dragonshrine of the undead vermin that now infest it. All it would take to prove yourself more noble and righteous than Alexstrasza herself is a quick jaunt over there and a few swings of a blade.\n\nI'm amused.", completion = "I'm trying to decide at which I'm more surprised... that you actually came to the aid of a Black Dragon or that you're still in one piece after speaking with Nalice.\n\nHer words drip venom, but I suppose Wyrmrest can keep even our kind in check sometimes.\n\nOr perhaps it's just the armies of the red dragonflight that are massed around her.", objectives = "Travel to the Obsidian Dragonshrine Northwest of Wymrest and just West of the Wrath Gate. Locate Serinar inside of the shrine and offer him your aid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12448] = { id = 12448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heated Battle", description = "The Scourge have overrun the shrine. The shrine's keeper, Dahlia Suntouch, is nowhere to be found. The red wyrms that fell in the shrine's defense now beset us in the form of twisted skeletal emberwyrms. The situation is dire, {race}.\n\nCaptain Drayzen leads a group of your kind in stemming the flow of the Scourge out of the shrine.\n\nGo to his aid... but please stay behind his men. The flow of Scourge is endless and I don't want to lose you in one of those scarred canyons.", progress = "I'm glad you're still with us, {race}.", completion = "It is a disgusting task, but I thank you for doing it.\n\nThe Scourge cannot be permitted to push any further out of the shrine lest all of these lands be overrun.", objectives = "Aid Captain Drayzen in holding the canyons by participating in the death of 12 Frigid Ghoul Attackers, 8 Frigid Geist Attackers, and 1 Frigid Abomination Attacker.\n\nReturn to Vargastrasz once you have finished this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12449] = { id = 12449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Earth", description = "I have another task that needs attention. I have brothers who are falling in the battle overhead and if we do not act quickly, they will only bolster the emberwyrm ranks.\n\nGet into the shrine through the pass in the south... the Scourge presence should be lighter there.\n\nSearch the shrine for ruby acorns that have fallen from the tree and plant them near the bodies of my fallen brood. Through this, they can give new life... a proud fate for any of my kind.", completion = "In the earth, my brothers can grant life anew. You have saved them from a fate far worse than death.\n\nI don't know a word in your tongue that could express how much this means to my kind. Thank you, {race}.", objectives = "Enter the Ruby Dragonshrine through the southern pass and search for Ruby Acorns. Use the Ruby Acorns on the fallen red dragons to return their bodies to the earth. Return to Vargastrasz once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12450] = { id = 12450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through Fields of Flame", description = "I have one final task for you, {race}... one that should turn the tide of this fight.\n\nReturn to the shrine and kill the necromancers that are fueling this onslaught. With them dead, we should be able to beat these forces back and eventually retake the shrine.\n\nI also need you to find the source of the corruption under the shrine and put an end to it.\n\nI know I have asked a lot of you, but if you do this for me, we will win this battle.", completion = "Dahlia... they turned her?\n\nDahlia has been loyal to us for a very long time... if they can corrupt a being of her devotion, it does not bode well for the rest of the young races. Thank you for freeing her. I hope she has found some peace.\n\nYou have honored us with your selfless assistance today, {race}. Perhaps not all of the Horde bear the black hearts of their ancestors.  I will send word to the council of what your kind have accomplished here.", objectives = "Enter the Ruby Dragonshrine through the southern pass, then kill 6 Frigid Necromancers and eliminate the source of the corruption under the shrine. Return to Vargastrasz once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12451] = { id = 12451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onward to Camp Oneqwah", description = "While we build Conquest Hold, I sent Scout Vor'takh to make contact with our taunka allies in the east. They're based in Camp Oneqwah, which is in the easternmost part of Grizzly Hills, beyond Grizzlemaw.\n\nMake the journey there, hear Vor'takh's report and offer your assistance with anything he and the local chieftain may need. Your contributions to Conquest Hold have been exemplary and I know Vor'takh will be grateful for the assistance.", completion = "<You offer a short introduction, explaining you were sent by Sergeant Nazgrim.>\n\nAh, so you're something in the way of reinforcements, then. Good.\n\nTormak and his men have need of your blade.", objectives = "Speak with Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12452] = { id = 12452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLD The Fate of the Ruby Dragonshrine", objectives = "Bring Dahlia's Ruby Broach to Ceristrasz and inform him of her fate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12453] = { id = 12453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes Above", description = "I've been asked to lend my support to our efforts against the Alliance.  At the moment our military forces are about evenly matched and we're looking for ways to find an edge.\n\nThe imperial eagles that fly over the mountains and trees in this area would make excellent scouts for us.  Take this silver feather and use it to bind my sight to that of them.\n\nBeing able to see our enemy's movements will grant us the strategic advantage we need.  You'll find abundant eagles in the mountains to the east.", completion = "I thank you, {name}.  Your help is appreciated.", objectives = "Windseer Grayhorn wants you to use the Silver Feather on 6 Imperial Eagles in Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12454] = { id = 12454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cycle of Life", description = "Ysera sleeps in the Emerald Dream, watching over both the Dream and Azeroth. But a horrible nightmare has taken hold in the Dream, and now I fear that Ysera is being affected by it.\n\nRecently, I asked her to aid in the fight against the Scourge that are raising frostwyrms at the other dragonshrines. She misunderstood.\n\nInstead, she told our dragonshrine's defenders to treat those not of the green dragonflight as enemies.\n\nI need you to slay some of the skytalons. The shrine must regain its balance.", progress = "The sooner that the emerald skytalons can be dealt with, the sooner the Emerald Dragonshrine can be returned to its natural balance.", completion = "Do not regret the part that you played in the cycle of life. Birth, death, and rebirth are all part of the natural order.", objectives = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to slay 5 Emerald Skytalons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12455] = { id = 12455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scattered To The Wind", description = "The munitions drop went badly, friend. The shipment of ammo from Westguard Keep was intercepted by the frostwyrms circling overhead. The flying machines were torn apart in a matter of seconds and their cargo was scattered to the wind. Most of it is still topside - on the Carrion Fields.\n\nI'm gonna need you to go back up and recover the munitions crates that are scattered all over this damned place.\n\nHurry it up! We can't start this offensive without guns and ammo, <buddy/missy>!", progress = "Where are my munitions, fella?", completion = "Just in time! Some of my soldiers got a little overzealous and decided to wade into the crypts directly to the east and west of us. Needless to say, they were quickly overwhelmed by those mindless ghouls. We need to rescue the survivors!", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to recover 8 Wintergarde Munitions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12456] = { id = 12456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Plume of Alystros", description = "I can feel that the shrine is not completely back in balance. The verdant keeper has been angered by our actions, and I sense that he will not listen to reason.\n\nAlystros is an immense skytalon who perches at the south end of the Emerald Dragonshrine. It is he who is in charge of the dragonshrine's aerial defenses. I fear that we will have to deal with him.\n\nTake these skytalon molts and place them on the ground where he can see them. He will come. Bring me his plume.", progress = "Have you managed to deal with Alystros? Do not be afraid to ask your friends for assistance.\n\nIn fact, given that the verdant keeper is very powerful, I recommend it!", completion = "Do not weep for Alystros. He has dedicated his eternal life to the defense of the Emerald Dragonshrine and will be reborn.\n\nHopefully when he returns to us, he will not be gripped with the confusion of the Emerald Nightmare that seems to have taken hold of The Dreamer.", objectives = "Nishera the Garden Keeper at the Emerald Dragonshrine has asked you to acquire The Plume of Alystros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12457] = { id = 12457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chain Gun And You", description = "We've set up chain guns and barricades directly to the east and to the west. Our injured soldiers are hiding in both rooms - trying their best to not alert the mindless ghouls to their presence.\n\nNow that we have ammo, I need you to man one of the chain guns and use it to blast a path clear for our soldiers! Once you're on board, call a soldier out from hiding and then lay down heavy fire to keep the Scourge off him!\n\nGet a move on!", progress = "Have you rescued our injured soldiers?", completion = "{name}, I haven't seen heroics like that since Silithus!\n\nI'll be sure that each and every one of those soldiers puts in a recommendation to Lord Fordragon that you be promoted!\n\nNow, on to more pressing matters. We've gotten reports back from our scouts that Thel'zan is close.", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to save 8 Injured 7th Legion Soldiers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12458] = { id = 12458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Lashers", description = "We need more weapons in the fight against the Scourge. The natural properties of the Emerald Dragonshrine to the southeast may be the answer.\n\nAny unliving creature, save those that Sylvanas has redeemed, that steps foot in the dragonshrine falls to dust.\n\nI want to test a theory, and I want you to be my instrument in doing so, young {race}. Go to the Emerald Dragonshrine and take the seeds from the emerald lashers therein.", progress = "And just how many seeds have you managed to acquire thus far?", completion = "Even now I can feel the pulse of nature from within these seeds.\n\nWe must put them to good use!", objectives = "Lord Itharius at the top of Wyrmrest Temple has asked you to return with 3 Lasher Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12459] = { id = 12459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Which Creates Can Also Destroy", description = "Since we only have three seeds, we must put them to the best possible use.\n\nYour targets are one of the reanimated frost wyrms circling to the north near Galakrond's Rest, Turgid the Vile in the ruined barracks at the Carrion Fields to the east, and Overseer Deathgaze at Jintha'kalar far to the northeast.\n\nWhile the seeds would outright destroy one of the lesser Scourge, they will greatly weaken these three. Enough so, in fact, that you should be able to handle them on your own.", completion = "Excellent. Just as I suspected all along. I shall have to attempt to contact Ysera and see if she approves.\n\nIf she can be coaxed from her nightmare, of course.\n\nThank you, {name}. You have been indispensable.", objectives = "Lord Itharius at the top of Wyrmrest Temple has asked you to destroy a Weakened Reanimated Frost Wyrm, Weakened Turgid the Vile, and Weakened Overseer Deathgaze.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12460] = { id = 12460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Ruby Dragonshrine", description = "We need you at the Ruby Dragonshrine.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. The situation seems dire, but this affords us a rare opportunity to establish a valuable alliance.\n\nI secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. If you have a fight in you, please go find Ceristrasz on the ridge east of the shrine and help him in any way that you can.", completion = "Ambassador Lauriel sent you?\n\nIf you talk to her again, please let her know that we are very appreciative of her aid. We are fighting battles on far too many fronts.", objectives = "Report to Ceristrasz on the ridge east of the Ruby Dragonshrine, west of Wyrmrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12461] = { id = 12461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Ruby Dragonshrine", description = "You are leaving to the Ruby Dragonshrine. This is not a request.\n\nThe dragons are beset on all sides by the blue flight and the scourge... they're in no better a state than we are. It is not often we are afforded the opportunity to redeem ourselves for the transgressions of our ancestors.\n\nI have secured a regiment to aid the red dragonflight against the Scourge at the Ruby Dragonshrine. Join them and crush the Scourge beneath your boots!\n\nFor the Horde!", completion = "Ambassador Golluck sent you?\n\nIf you talk to him again, please let him know that we are very appreciative of his aid. We are fighting battles on far too many fronts.", objectives = "Report to Vargastrasz on a ridge outside of the Ruby Dragonshrine, just east of Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12462] = { id = 12462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Off A Piece", description = "Just down the steps lies the gateway to damnation: Scourge as far as the eye can see and getting thicker with each passing moment. What little intelligence we've been able to gather indicates that two Scourge necrolords are furiously working at emptying the first two crypts down below. Before we can breach the inner chamber to Thel'zan, we'll need to take care of those two clowns and their Naxxramas cronies.\n\nGo down into the mausoleum and take out the necrolords and the Naxxramas dreadguards and shades.", progress = "Did you break yourself off a piece?", completion = "That oughta buy Ambo a little bit of time to get things situated.", objectives = "Yord \"Calamity\" Icebeard at the Wintergarde Mausoleum in Dragonblight wants you to kill Necrolord X'avius, Necrolord Horus, and 15 Naxxramas Scourge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12463] = { id = 12463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderbeard Must Be Found!", description = "There's been talk of a tunnel dug by Scourge that connects the embalming chambers of the mausoleum with the large crypts, now unearthed by Thel'zan and his minions. I recently sent my best rogue, Plunderbeard, in search of answers, but have yet to hear back from him. If I were a betting man I'd wager that he's a goner.\n\nI want you to go down those steps and head straight through the embalming chamber and look for Plunderbeard. Dead or alive, he'll have answers.", completion = "<You discover a journal on Plunderbeard's corpse.>\n\nEntry One:\n\nThey drag corpses through the tunnel to the embalming room for experimentation. There is an endless supply in this mausoleum. Whatever cannot be reanimated is turned into a bone construct of one kind or another.\n\nEntry Two:\n\nI fear that this lich, Thel'zan, hides a dark secret. Who is he? Was he once... one of us?\n\nEntry Three: I have discovered the location of the lich's phylactery. It is...\n\n<The rest of the pages are torn out.>", objectives = "Ambo Cash at the Wintergarde Mausoleum in Dragonblight wants you to find Plunderbeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12464] = { id = 12464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Old Enemy", description = "My old enemy, High General Abbendis, has come to Northrend.\n\nSomehow she survived the attacks upon Tyr's Hand and brought a small force north. They've established New Hearthglen to the south.\n\nWhile they could prove useful in fighting the Scourge, Abbendis herself is far too shrewd an opponent to let live. Trust me, if we let them stand, she will be at our throats before the dust settles.\n\nSo, we'll deprive them of their leadership and go about our business. Bring me her head as proof.", progress = "It is done then?", completion = "An unfortunate, but necessary action that we had to take in dealing with Abbendis. In another lifetime, I think I could have imagined fighting side-by-side with her.\n\n<The commander's voice trails off as he reflects a moment before proceeding.>\n\nI'm a little concerned about this grand admiral you describe. Barean Westwind you say? I can't believe that he's still alive. He must be ancient. We'll have to deal with him later, however.\n\nIn the meantime, I think you've earned a reward and a little R & R.", objectives = "Deliver The High General's Head to Commander Eligor Dawnbringer at Wintergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12465] = { id = 12465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunderbeard's Journal", description = "Whatever was written on the remaining pages of Plunderbeard's journal must be recovered. Search the chambers located on the other side of this tunnel for Plunderbeard's assailants. They must be the ones who tore the journal apart!\n\nShould you recover the missing pages, return them to Ambo Cash at the entrance of the Wintergarde Mausoleum.", progress = "I certainly don't feel like a winner...", completion = "<Ambo reads through the recovered journal pages.>\n\nThere's some good news and there's some bad news. Which do you want first?\n\nAh hell, why give you a choice? The good news is that if we can get Thel'zan's phylactery, we can destroy him. The bad news is that the phylactery is on a rather large frostwyrm.", objectives = "Recover Page 4 of Plunderbeard's Journal, Page 5 of Plunderbeard's Journal, Page 6 of Plunderbeard's Journal, and Page 7 of Plunderbeard's Journal and return them to Ambo Cash at the Wintergarde Mausoleum in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12466] = { id = 12466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Icestorm: The 7th Legion Front", description = "You need to get to the 7th Legion Front in northern Dragonblight. Return to Wintergarde Keep and take the north gate out of town. Keep north until you hit a road. Take a left on that road and follow it until you reach the snowline. Once at the snowline keep heading west until you hit the Path of the Titans. Follow that north and it'll lead you right into the 7th Legion Front.\n\nOnce there, speak with Legion Commander Tyralion. He'll be expecting you.\n\nAnd {name} - it has been a pleasure. Farewell.", completion = "Now you know why they call this the Dragon Wastes. Bones of the beasts are strewn about as far as the eye can see.\n\nWe've probably taken down a dozen or more frostwyrms and there's still no end in sight. The Scourge's got fuel for ten-thousand more what with all the bones laying about.\n\n<Tyralion clears his throat.>\n\nI don't mean to bore you with the details, hero. We've got the wyrm you're looking for locked in our sights.", objectives = "Report to Legion Commander Tyralion at the 7th Legion Front in central Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12467] = { id = 12467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing Icestorm: Thel'zan's Phylactery", description = "Your frostwyrm is out there.\n\n<Tyralion points west.>\n\nAnd it's a big one!\n\nWhen you're ready to fight, go speak with \"Wyrmbait.\" He'll \"fetch\" her. Once Icestorm is close enough we'll chain her to the ground and finish her off! Hopefully, with your help, we'll be able to take her down and get you that phylactery.\n\nOnce you've got the phylactery, return to Wintergarde Keep and report to High Commander Halford Wyrmbane. He's been making preparations for the final showdown with Thel'zan.", progress = "Have you recovered Thel'zan's phylactery?", completion = "We've lost so many good soldiers to that monster, Thel'zan. I wish I could be there to see you crush his phylactery in front of him and end his existence.", objectives = "Recover Thel'zan's Phylactery from Icestorm and return it to High Commander Halford Wyrmbane at Wintergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12468] = { id = 12468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conqueror's Task", description = "The Horde is a magnificent war machine and you are nothing but a cog.\n\nI am in charge of securing fuel for this machine.  If I fail, the machine fails.\n\nLumber, ore, water... it's all here and we want it.  And so does the Alliance.\n\nBefore we can move against the human scum, we need to solidify our control over the western region.\n\nSpeak to Sergeant Nazgrim about eradicating the vrykul in Voldrune and then maybe - if you turn out to not be a complete failure - we'll send you on further tasks.", completion = "So Krenna sent you to me?  She must've not liked you very much, but then again who does she like?\n\nCracking this vrykul outpost is going to be a tough, tough job.", objectives = "Speak to Sergeant Nazgrim in Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12469] = { id = 12469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Sender", description = "Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate.\n\nIt appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.", progress = "Hello there!", completion = "Hah! We lost another one, eh? Those harpies are becoming a real nuisance.\n\nNo matter! There's work to be done. Lend a hand around here, will ya?", objectives = "Follow the ridge to the east and deliver the pack of explosives to Xink at Nozzlerust Post in northern Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12470] = { id = 12470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Infinite", description = "A time storm at the Bronze Dragonshrine to the northeast is keeping immortals from entering.\n\nThe Infinite Dragonflight are in a fight inside with the defenders to wrest control of the dragonshrine. We must take this opportunity to gain information.\n\nYou are not immortal. You can cross into the dragonshrine and use the Hourglass of Eternity. Protect the hourglass for long enough and the leader of the Infinite Dragonflight should be revealed.\n\nBe warned, the Infinite Dragonflight will try to stop you!", progress = "What news do you bring? What happened at the Bronze Dragonshrine?\n\nDid you find out who the leader of the Infinite Dragonflight is?", completion = "You saw Nozdormu? That doesn't make any sense.\n\n<Chromie thinks a moment about what you've said.>\n\nActually, that's great news! We had no idea of where or when the Lord of Time had gone to. We just knew that he had disappeared to deal with very important matters.\n\nSo, even though the leader of the Infinite Dragonflight wasn't revealed, you've discovered that Nozdormu is alive and well, and fighting back against them!\n\nThank you, {name}. I'll be seeing you soon!", objectives = "Chromie, at the top of Wyrmrest Temple, has asked you to travel to the Bronze Dragonshrine. Once inside, place the Hourglass of Eternity on the ground.\n\nProtect the hourglass for as long as it lasts and then return to her with whatever information you gain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12471] = { id = 12471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cruelty of the Kvaldir", description = "I thank you for saving me, {name}.  The kvaldir are animals!\n\nThey made us fight the other prisoners.  It would've been more merciful to just kill us all.\n\nThe youngling Karuk is still alive -- I noticed him arrive here.  Tell him his father fought until the end.", completion = "I thank you, {name}.  You've shown a great deal of goodwill towards my clan.", objectives = "Speak to Karuk about the Captured Tuskarr Prisoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12472] = { id = 12472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finality", description = "Thanks to your heroics, Lord Fordragon has given the command to launch a full assault against Thel'zan. 7th Legion have made their way into the summoning chamber of the mausoleum and located what appears to be a gateway to hell. The only piece that's missing now is you.\n\nTake the phylactery and report to Legion Commander Yorik inside the Wintergarde Mausoleum.\n\nThere is a tunnel that the Scourge dug out just outside the keep that you can take to get to Yorik quickly. Go now, {name}! Lead us to victory!", progress = "<Yorik lets out a sigh of relief.>\n\nWe thought you might not show up, {name}.", completion = "When you're ready I'll place the phylactery out in front of the gateway and call forth Thel'zan.", objectives = "Take Thel'zan's Phylactery to Legion Commander Yorik inside the Wintergarde Mausoleum in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12473] = { id = 12473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End And A Beginning", description = "Every good story has a beginning and an ending, {name}. While your story is far from over, I'll be damned if it's not already turning out to be the stuff of legend! No matter what happens to us when this is all over, what you've done at Wintergarde will be a tale told for years to come.\n\nNow, ally, when you are ready I will use the phylactery to coax Thel'zan out of hiding.\n\nShould we somehow succeed, report the victory to High Commander Halford Wyrmbane at Wintergarde Keep.", completion = "Wintergarde is saved because of you, {name}. To think that one man could so swiftly turn the tides of battle is hard for most to comprehend; yet here we are - victorious! You have managed to restore the faith of these people and earned the respect of your commanding officers.\n\n \n\nLord Fordragon has returned to Angrathar to prepare our forces for the destruction of the Wrathgate and has requested that you join him! I couldn't recommend a better soldier for the job, {name}.", objectives = "Defeat Thel'zan the Duskbringer and report to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12474] = { id = 12474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Fordragon Hold!", description = "With the Naxxramas war machine stopped dead in its tracks the time has come for you to help our forces at Angrathar, the Wrathgate. Nestled against the mountain in northern Dragonblight is our base of operations, Fordragon Hold. It is there that Lord Fordragon awaits your arrival! Go now, {name}!\n\nTake the north gate out of town and travel north by northwest until you arrive at your destination.\n\nLight protect you!", completion = "This commendation is only given to those who have gone above and beyond the call of duty in the name of the Alliance. I could count the number of times I've handed this one out on one hand, {name}, and never has anyone been more deserving than you! Congratulations!\n\nNow, let us look upon the Wrathgate. Does it look familiar? It should. That strange ore you found at the Wintergarde Mine is exactly what the Wrathgate is made from. We will find its weakness and expose it for all to see! First, though...", objectives = "Venture to Fordragon Hold in Dragonblight and speak with Highlord Bolvar Fordragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12475] = { id = 12475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Secrets Men Hide", description = "After the betrayal at the Forgotten Shore, Prince Arthas - with Muradin in tow - began his quest for Frostmourne. Could the location of the cavern where Frostmourne was found be near? What secrets could it hold? While the orb has no answers for these questions, it does show me something.\n\nTo the northeast of Wintergarde Keep is an outpost built by the Scarlet Onslaught. Somewhere within that outpost is a map. The orb tells me that this map will be of great use to us.\n\nRetrieve it!", progress = "Have you recovered the Onslaught map?", completion = "A cave? Could it be? There can be no other correlation!", objectives = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to find the Onslaught Map and return it to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12476] = { id = 12476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of the Crusade?", description = "To the northeast of Wintergarde Keep is a newly built encampment, set up by the Scarlet Crusade - or rather - the Scarlet Onslaught as they now call themselves. While we are unsure as to why they are in Northrend, they are certainly no less dangerous than they were before. As of last night the Scarlet Onslaught has killed twelve of our soldiers. They must be taught a lesson, {name}.\n\nGo to Onslaught Base Camp and thin them out.", completion = "Hopefully the message is now clear to the Onslaught. I hope it was enough of a beating to make them doubt their affiliations.", objectives = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 20 Scarlet Onslaught at the Onslaught Base Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12477] = { id = 12477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path of Redemption", description = "\"The Path of Redemption,\" ever heard of it? It is allegedly a journal that holds the prophetic ramblings of High General Abbendis of the Scarlet Onslaught. Within that book can be found the motivations and goals of the Scarlet zealots - not to mention a whole lot of insanity.\n\nVenture to Onslaught Base Camp, northeast of Wintergarde Keep, and recover a copy of \"The Path of Redemption\" from one of the Onslaught soldiers.", progress = "Did you find a copy?", completion = "<Halford reads the journal.>\n\nAbbendis has gone off the deep end. The Light speaks to her now?\n\nDespite the inane ramblings, this journal gives us a never before seen look into the mind of the Scarlet zealots. This was a great find, {name}. Lord Fordragon will be pleased.", objectives = "Return \"The Path of Redemption\" to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12478] = { id = 12478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmourne Cavern", description = "They have labeled the cave as Frostmourne Cavern. Why the Scarlet Onslaught is interested in such things is unknown, but by the look of things, the area surrounding the cave is heavily guarded. Nonetheless, we must proceed!\n\nTake this scrying orb and travel north out of town and then northwest toward Scarlet Point. Make your way into the cave and battle your way to the bottom. Once there, use the orb. Return here with what you discover.", progress = "Have you searched Frostmourne Cavern?", completion = "Muradin lives? Could it be? I must notify King Bronzebeard at once!\n\nI need to consult the orb. There must be more information - somewhere!", objectives = "Use Zelig's Scrying Orb at the bottom of Frostmourne Cavern. Unlock the secrets of the past!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12479] = { id = 12479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", objectives = "Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12480] = { id = 12480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrath of the Lich King: Onwards to Northrend!", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.", sourceObjective = "Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.", sourceObjectiveStatus = "unverified-source-field" }
quests[12481] = { id = 12481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adding Injury to Insult", description = "The vrykul are being clever about this.  Fortunately I've a trick up my sleeve.\n\nThis leader of theirs, Bjorn, is a real hothead.  We've pieced together enough of their language to fashion what we think is a good insult.  Something involving his mother and large barnyard animals... we're not quite sure.\n\nTake this piece of paper and read it to him.  Once he starts chasing you, lure him back here.  We'll make sure he doesn't make it out alive.", progress = "Assassination work isn't as glamorous as it's made out to be.", completion = "Nice work.  That poor sap never saw it coming.", objectives = "Read the Vrykul Insult to Bjorn Halgurdsson in Baleheim, then lead him back to Lydell's Ambush and help slay him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12482] = { id = 12482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Against Nifflevar", description = "We await reinforcements from Vengeance Landing to move against Nifflevar.  If we were to capture it earlier, though, it would provide us with a great advantage over the Alliance.\n\nHead into town and see if you can put a dent in their numbers.", completion = "Excellent work, {name}.  When our forces from Vengeance Landing arrive, we'll be able to take care of any vrykul that are left.", objectives = "Ranger Captain Areiel wants you to go to Nifflevar and slay 5 Dragonflayer Warriors, 4 Dragonflayer Rune-Seers and 4 Dragonflayer Hunting Hounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
